#!/usr/bin/env python3
"""Hash pins and checks for openpcbsi's external dependencies (stdlib only; run with `python3 -I`).

    python3 deps/pins.py hash [--check]          regenerate requirements/*.txt from requirements/*.in
    python3 deps/pins.py site SITE REQ.txt ...   check an installed site against hashed pins
    python3 deps/pins.py sdist DEPS SECTION      check a parser clone against its PyPI sdist

hash: every `name==version` in requirements/X.in becomes a line in requirements/X.txt carrying the
SHA-256 of each wheel PyPI lists for that version that fits the target Pythons (`# pythons:` in the
.in file) on Linux (manylinux x86_64, aarch64), macOS (x86_64, arm64) or Windows (x86-64). Hashes
come from PyPI's JSON API (https://pypi.org/pypi/NAME/VERSION/json). Wheels only: the setup scripts
install with --only-binary :all:, so no sdist is built (a build would fetch unhashed build tools).
--check regenerates in memory and reports a difference instead of writing.

site: the distributions installed in SITE must be exactly the pins (same names, same versions, none
missing, none extra), every installed file must still match the SHA-256 in its RECORD, and no
file may be there that no package's RECORD lists
(byte-code caches excepted: the interpreter rewrites them).

sdist: the sdist named by parsers.lock's `sdist_url` is fetched (cached in DEPS/.pip-cache/sdist) and
its SHA-256 compared with `sdist_sha256`; then every file under its `sdist_tree` must equal, byte for
byte, the file tracked by git under `clone_tree` in the clone, and the two file sets must be the same.
"""
import base64
import csv
import hashlib
import io
import json
import os
import re
import subprocess
import sys
import tarfile
import tomllib
import urllib.request

HERE = os.path.dirname(os.path.abspath(__file__))
REQ_DIR = os.path.join(HERE, "requirements")
UA = {"User-Agent": "openpcbsi-pins (urllib)"}

# platform groups a wheel may serve; "any" wheels serve all of them
GROUPS = {
    "linux-x86_64": re.compile(r"^manylinux.*_x86_64$"),
    "linux-aarch64": re.compile(r"^manylinux.*_aarch64$"),
    "macos-x86_64": re.compile(r"^macosx_\d+_\d+_(x86_64|intel|universal2)$"),
    "macos-arm64": re.compile(r"^macosx_\d+_\d+_(arm64|universal2)$"),
    "windows-x86_64": re.compile(r"^win_amd64$"),
}
REQUIRED = "linux-x86_64"          # the platform openpcbsi is tested on: a missing wheel is an error


def norm(name):
    return re.sub(r"[-_.]+", "-", name).lower()


def fail(msg):
    print(f"ERROR: {msg}", file=sys.stderr)
    sys.exit(1)


# ---------------------------------------------------------------------------------------- hash

def read_in(path):
    """Pins (name, version, marker) and the target Pythons of a .in file."""
    pins, pythons = [], ["3.12"]
    for line in open(path):
        m = re.match(r"#\s*pythons:\s*(.+)", line)
        if m:
            pythons = m.group(1).split()
            continue
        line = line.split("#")[0].strip()
        if not line:
            continue
        m = re.fullmatch(r"([A-Za-z0-9][A-Za-z0-9._-]*)==([^\s;]+)\s*(?:;\s*(.+))?", line)
        if not m:
            fail(f"{path}: not an exact pin: {line!r}")
        pins.append((m.group(1), m.group(2), (m.group(3) or "").strip()))
    return pins, pythons


def wheel_tags(filename):
    parts = filename[:-4].split("-")
    py, abi, plat = parts[-3:]
    return py.split("."), abi.split("."), plat.split(".")


def py_ok(pys, abis, version):
    minor = int(version.split(".")[1])
    for abi in abis:
        if abi == "none" and any(p in ("py3", f"py3{minor}", f"cp3{minor}") for p in pys):
            return True
        if abi == "abi3" and any(re.fullmatch(r"cp3(\d+)", p) and int(p[3:]) <= minor for p in pys):
            return True
        if abi == f"cp3{minor}" and f"cp3{minor}" in pys:
            return True
    return False


def groups_of(plats):
    if "any" in plats:
        return set(GROUPS)
    return {g for g, rx in GROUPS.items() for p in plats if rx.match(p)}


def pypi_files(name, version):
    url = f"https://pypi.org/pypi/{name}/{version}/json"
    try:
        with urllib.request.urlopen(urllib.request.Request(url, headers=UA), timeout=60) as r:
            return json.load(r)["urls"]
    except Exception as e:  # noqa: BLE001 -- any failure here must stop the regeneration
        fail(f"{name}=={version}: cannot read {url}: {e}")


def render(in_path):
    pins, pythons = read_in(in_path)
    rel = os.path.relpath(in_path, HERE)
    out = [f"# Generated by `python3 deps/pins.py hash` from deps/{rel}: do not edit by hand.",
           f"# Wheel SHA-256s from PyPI's JSON API for CPython {', '.join(pythons)} on "
           + ", ".join(GROUPS) + ".",
           "# Install with: pip install --require-hashes --only-binary :all: -r <this file>"]
    notes, body = [], []
    for name, version, marker in pins:
        groups_wanted = {g for g in GROUPS if g.startswith("macos")} if "darwin" in marker else set(GROUPS)
        hashes, cover = set(), set()
        for f in pypi_files(name, version):
            if f["packagetype"] != "bdist_wheel":
                continue
            pys, abis, plats = wheel_tags(f["filename"])
            okpy = [v for v in pythons if py_ok(pys, abis, v)]
            gs = groups_of(plats) & groups_wanted
            if not okpy or not gs:
                continue
            hashes.add(f["digests"]["sha256"])
            if f.get("yanked"):
                notes.append(f"# note: {f['filename']} is yanked on PyPI")
            cover |= {(v, g) for v in okpy for g in gs}
        missing = sorted((v, g) for v in pythons for g in groups_wanted if (v, g) not in cover)
        if any(g == REQUIRED for _, g in missing) and "darwin" not in marker:
            fail(f"{name}=={version}: no wheel on PyPI for "
                 + ", ".join(f"CPython {v} {g}" for v, g in missing if g == REQUIRED))
        if missing:
            notes.append(f"# no wheel: {name}=={version} for "
                         + ", ".join(f"{v} {g}" for v, g in missing))
        req = f"{name}=={version}" + (f" ; {marker}" if marker else "")
        body.append(" \\\n".join([req] + [f"    --hash=sha256:{h}" for h in sorted(hashes)]))
    return "\n".join(out + notes + body) + "\n"


def cmd_hash(args):
    check = "--check" in args
    ins = sorted(f for f in os.listdir(REQ_DIR) if f.endswith(".in"))
    bad = 0
    for f in ins:
        src, dst = os.path.join(REQ_DIR, f), os.path.join(REQ_DIR, f[:-3] + ".txt")
        text = render(src)
        old = open(dst).read() if os.path.exists(dst) else None
        if check:
            state = "ok" if text == old else "DIFFERS from PyPI / the .in pins"
            bad += text != old
            print(f"requirements/{f[:-3]}.txt: {state}")
        elif text != old:
            open(dst, "w").write(text)
            print(f"wrote requirements/{f[:-3]}.txt")
        else:
            print(f"requirements/{f[:-3]}.txt unchanged")
    sys.exit(1 if bad else 0)


# ---------------------------------------------------------------------------------------- site

def read_txt_pins(path):
    """name -> version for the pins in a hashed .txt that apply to this platform."""
    pins = {}
    text = open(path).read().replace("\\\n", " ")
    for line in text.splitlines():
        line = line.split("#")[0].strip()
        if not line:
            continue
        m = re.match(r"([A-Za-z0-9][A-Za-z0-9._-]*)==([^\s;]+)\s*(?:;\s*(.*?))?\s*(--hash.*)?$", line)
        if not m:
            fail(f"{path}: cannot read {line!r}")
        marker = (m.group(3) or "").strip()
        if marker:
            mm = re.fullmatch(r'sys_platform\s*(==|!=)\s*"([^"]+)"', marker)
            if not mm:
                fail(f"{path}: marker {marker!r} is not supported by pins.py")
            if (sys.platform == mm.group(2)) != (mm.group(1) == "=="):
                continue
        pins[norm(m.group(1))] = m.group(2)
    return pins


def record_problems(site, dist_info, listed=None):
    bad, n = [], 0
    rec = os.path.join(site, dist_info, "RECORD")
    if not os.path.exists(rec):
        return [f"{dist_info}: no RECORD"], 0
    for row in csv.reader(open(rec, newline="")):
        path = os.path.normpath(os.path.join(site, row[0])) if row else ""
        m = re.fullmatch(r"(?:\.\./)+bin/([^/]+)", row[0]) if row else None
        if m and not os.path.exists(path):
            # pip --target writes RECORD for scripts relative to its build prefix; they land in SITE/bin
            path = os.path.join(site, "bin", m.group(1))
        if listed is not None and path:
            listed.add(os.path.normpath(path))
        if len(row) < 2 or not row[1] or row[0].endswith(".pyc"):
            continue                # byte-code caches: the interpreter rewrites them (PySide6 ships some)
        n += 1
        algo, _, want = row[1].partition("=")
        if not os.path.exists(path):
            bad.append(f"{row[0]} missing")
            continue
        h = hashlib.new(algo, open(path, "rb").read()).digest()
        if base64.urlsafe_b64encode(h).rstrip(b"=").decode() != want:
            bad.append(f"{row[0]} modified")
    return bad, n


def cmd_site(args):
    if len(args) < 2:
        fail("usage: pins.py site SITE REQ.txt [REQ.txt ...]")
    site, reqs = args[0], args[1:]
    want = {}
    for r in reqs:
        want.update(read_txt_pins(r))
    have, info = {}, {}
    for d in os.listdir(site):
        if d.endswith(".dist-info"):
            meta = open(os.path.join(site, d, "METADATA"), encoding="utf-8", errors="replace").read()
            name = re.search(r"^Name:\s*(\S+)", meta, re.M).group(1)
            ver = re.search(r"^Version:\s*(\S+)", meta, re.M).group(1)
            have[norm(name)], info[norm(name)] = ver, d
    problems = []
    for n in sorted(set(want) - set(have)):
        problems.append(f"missing: {n}=={want[n]}")
    for n in sorted(set(have) - set(want)):
        problems.append(f"not pinned: {n}=={have[n]}")
    for n in sorted(set(want) & set(have)):
        if want[n] != have[n]:
            problems.append(f"version: {n} is {have[n]}, pinned {want[n]}")
    nfiles = 0
    listed = set()
    for n in sorted(have):
        bad, k = record_problems(site, info[n], listed)
        nfiles += k
        problems += [f"{n}: {b}" for b in bad]
    # a file no installed package lists (a planted module would be imported like any other): an extra
    for root, dirs, files in os.walk(site):
        dirs[:] = [d for d in dirs if d != "__pycache__"]
        for f in files:
            fp = os.path.normpath(os.path.join(root, f))
            if fp not in listed and not f.endswith(".pyc"):
                problems.append(f"not listed by any package: {os.path.relpath(fp, site)}")
    for p in problems:
        print(f"  {p}", file=sys.stderr)
    if problems:
        fail(f"{site}: {len(problems)} difference(s) from {', '.join(map(os.path.basename, reqs))}")
    print(f"{site}: {len(have)} distributions match the pins; {nfiles} installed files match their RECORD hashes")


# ---------------------------------------------------------------------------------------- sdist

def cmd_sdist(args):
    if len(args) != 2:
        fail("usage: pins.py sdist DEPS SECTION")
    deps, sec = args
    lk = tomllib.load(open(os.path.join(HERE, "parsers.lock"), "rb"))[sec]
    url, want = lk["sdist_url"], lk["sdist_sha256"]
    cache = os.path.join(deps, ".pip-cache", "sdist")
    os.makedirs(cache, exist_ok=True)
    path = os.path.join(cache, os.path.basename(url))
    if os.path.exists(path):
        data, where = open(path, "rb").read(), "cached"
    else:
        with urllib.request.urlopen(urllib.request.Request(url, headers=UA), timeout=120) as r:
            data, where = r.read(), "downloaded"
    got = hashlib.sha256(data).hexdigest()
    if got != want:
        if os.path.exists(path):
            os.remove(path)
        fail(f"{sec}: SHA-256 MISMATCH for {os.path.basename(url)} ({where}): "
             f"got {got}, parsers.lock records {want}")
    if where == "downloaded":
        open(path, "wb").write(data)
    tf = tarfile.open(fileobj=io.BytesIO(data))
    root = tf.getnames()[0].split("/")[0]
    pre = f"{root}/{lk['sdist_tree']}/"
    sd = {m.name[len(pre):]: hashlib.sha256(tf.extractfile(m).read()).hexdigest()
          for m in tf.getmembers() if m.isfile() and m.name.startswith(pre)}
    clone, ctree = os.path.join(deps, lk["dir"]), lk["clone_tree"]
    tracked = subprocess.run(["git", "-C", clone, "ls-files", "-z", "--", ctree], check=True,
                             capture_output=True, text=True).stdout.split("\0")
    gt = {f[len(ctree) + 1:]: hashlib.sha256(open(os.path.join(clone, f), "rb").read()).hexdigest()
          for f in tracked if f}
    diff = ([f"only in sdist: {k}" for k in sorted(set(sd) - set(gt))]
            + [f"only in clone: {k}" for k in sorted(set(gt) - set(sd))]
            + [f"differs: {k}" for k in sorted(set(sd) & set(gt)) if sd[k] != gt[k]])
    if not sd:
        diff.append(f"sdist has no files under {lk['sdist_tree']}/")
    for d in diff[:50]:
        print(f"  {d}", file=sys.stderr)
    if diff:
        fail(f"{sec}: the clone's {ctree}/ does not match {os.path.basename(url)} ({len(diff)} differences)")
    print(f"{sec}: sdist SHA-256 ok ({where}); clone {lk['dir']}/{ctree} == sdist {lk['sdist_tree']}/ "
          f"({len(sd)} files)")


if __name__ == "__main__":
    cmds = {"hash": cmd_hash, "site": cmd_site, "sdist": cmd_sdist}
    if len(sys.argv) < 2 or sys.argv[1] not in cmds:
        print(__doc__)
        sys.exit(2)
    cmds[sys.argv[1]](sys.argv[2:])
